P.saveNode=async function(id,label){if(this.uploading?.size)throw Error('文件正在上传，请等待完成后保存');const node=this.library.tree.nodes.find(n=>n.id===id),ids=new Set([id,...this.library.tree.nodes.filter(n=>n.parent===id).map(n=>n.id)]);const drafts=Object.entries(this.drafts).filter(([key,d])=>d.dirty&&ids.has(d.layout?.module_id));await Promise.all(drafts.map(([key])=>this.queues.get(key)));const requests=drafts.map(([key,d])=>{const e=this.entry(d.id),saved=this.selected.get(e.id);this.selected.set(e.id,key.slice(e.id.length+1));const r=this.request(e);if(saved)this.selected.set(e.id,saved);else this.selected.delete(e.id);return r;});const result=await api('/api/profile/tree',{revision:this.library.tree.revision,action:'save',id,label,records:requests});drafts.forEach(([key])=>delete this.drafts[key]);this.persist();await this.reload();this.renderedModule=null;this.render();toast('已保存'+(node.kind==='major'?'大模块':'子模块')+'及其下的资料草稿');};
